1	using Microsoft.Data.SqlClient;
2	using Microsoft.EntityFrameworkCore;
3	using seed_a_backend.Api.Data;
4	using seed_a_backend.Api.DTOs;
5	using seed_a_backend.Api.Models;
6	
7	namespace seed_a_backend.Api.Services;
8	
9	public class BuchungenService(AppDbContext db, IReferenzGenerator referenzGenerator) : IBuchungenService
10	{
11	    private const int MaxReferenzVersuche = 5;
12	
13	    public async Task<BuchungErgebnis> BuchungAnlegenAsync(string veranstaltungId, BuchungAnlegenRequestDto request)
14	    {
15	        var veranstaltung = await db.Veranstaltungen
16	            .Include(v => v.Preiskategorien)
17	            .FirstOrDefaultAsync(v => v.Id == veranstaltungId);
18	
19	        if (veranstaltung is null)
20	        {
21	            return BuchungErgebnis.VeranstaltungFehlt();
22	        }
23	
24	        foreach (var position in request.Positionen)
25	        {
26	            if (veranstaltung.Preiskategorien.All(p => p.Id != position.PreiskategorieId))
27	            {
28	                return BuchungErgebnis.PreiskategorieFehlt(position.PreiskategorieId);
29	            }
30	        }
31	
32	        var angefragteCodes = request.Positionen.Select(p => p.SitzplatzCode).ToList();
33	
34	        if (angefragteCodes.Count != angefragteCodes.Distinct().Count())
35	        {
36	            return BuchungErgebnis.SitzplatzDuplikat();
37	        }
38	
39	        for (var versuch = 1; versuch <= MaxReferenzVersuche; versuch++)
40	        {
41	            var buchung = new Buchung
42	            {
43	                Id = Guid.NewGuid().ToString(),
44	                Referenz = referenzGenerator.Naechste(),
45	                VeranstaltungId = veranstaltungId,
46	                Name = request.Name,
47	                Email = request.Email,
48	                Status = BuchungStatus.Aktiv,
49	                Gesamtpreis = 0m,
50	            };
51	
52	            var positionen = new List<Buchungsposition>();
53	            var gesamtpreis = 0m;
54	            foreach (var position in request.Positionen)
55	            {
56	                var kategorie = veranstaltung.Preiskategorien.First(p => p.Id == position.PreiskategorieId);
57	                gesamtpreis += kategorie.Preis;
58	                positionen.Add(new Buchungsposition
59	                {
60	                    BuchungId = buchung.Id,
61	                    SitzplatzCode = position.SitzplatzCode,
62	                    PreiskategorieId = kategorie.Id,
63	                    PreisSnapshot = kategorie.Preis,
64	                });
65	            }
66	
67	            buchung.Gesamtpreis = gesamtpreis;
68	
69	            var belegungen = request.Positionen.Select(position => new Sitzplatzbelegung
70	            {
71	                VeranstaltungId = veranstaltungId,
72	                SitzplatzCode = position.SitzplatzCode,
73	                BuchungId = buchung.Id,
74	            }).ToList();
75	
76	            await using var transaction = await db.Database.BeginTransactionAsync();
77	            db.Buchungen.Add(buchung);
78	            db.Buchungspositionen.AddRange(positionen);
79	            db.Sitzplatzbelegungen.AddRange(belegungen);
80	
81	            try
82	            {
83	                await db.SaveChangesAsync();
84	                await transaction.CommitAsync();
85	
86	                return BuchungErgebnis.Erfolg(new BuchungDto(
87	                    buchung.Referenz,
88	                    buchung.VeranstaltungId,
89	                    buchung.Name,
90	                    buchung.Email,
91	                    buchung.Status.ToString(),
92	                    buchung.Gesamtpreis,
93	                    positionen.Select(p => new BuchungspositionDto(
94	                        p.SitzplatzCode,
95	                        p.PreiskategorieId,
96	                        veranstaltung.Preiskategorien.First(k => k.Id == p.PreiskategorieId).Name,
97	                        p.PreisSnapshot)).ToList()));
98	            }
99	            catch (DbUpdateException ex)
100	            {
101	                await transaction.RollbackAsync();
102	                db.ChangeTracker.Clear();
103	
104	                var tatsaechlichBelegt = await db.Sitzplatzbelegungen
105	                    .Where(s => s.VeranstaltungId == veranstaltungId && angefragteCodes.Contains(s.SitzplatzCode))
106	                    .Select(s => s.SitzplatzCode)
107	                    .ToListAsync();
108	
109	                if (tatsaechlichBelegt.Count > 0)
110	                {
111	                    return BuchungErgebnis.Konflikt(tatsaechlichBelegt);
112	                }
113	
114	                if (ex.InnerException is not SqlException { Number: 2601 or 2627 })
115	                {
116	                    // Keiner der angefragten Plaetze ist belegt, und der Fehler ist keine
117	                    // UNIQUE-Constraint-Verletzung (SQL-Fehlercodes 2601/2627 fuer Index bzw.
118	                    // Primaerschluessel) - z.B. ein Deadlock oder Verbindungsabbruch. Das ist keine
119	                    // Referenz-Kollision und darf nicht als solche wegretryt werden.
120	                    throw;
121	                }
122	
123	                // Keiner der angefragten Plaetze ist tatsaechlich belegt und der Fehler ist eine
124	                // UNIQUE-Constraint-Verletzung: der Fehlschlag kam von der UNIQUE-Constraint auf
125	                // Buchung.Referenz. Naechster Versuch mit neuer Referenz (bis MaxReferenzVersuche
126	                // erreicht ist).
127	            }
128	        }
129	
130	        return BuchungErgebnis.ReferenzFehlgeschlagen();
131	    }
132	
133	    public async Task<BuchungDetailDto?> BuchungAbrufenAsync(string referenz)
134	    {
135	        var referenzNormalisiert = referenz.Trim().ToUpperInvariant();
136	
137	        return await db.Buchungen
138	            .Where(b => b.Referenz == referenzNormalisiert)
139	            .Select(b => new BuchungDetailDto(
140	                b.Referenz,
141	                b.VeranstaltungId,
142	                b.Veranstaltung!.Titel,
143	                b.Veranstaltung!.Zeitpunkt,
144	                b.Veranstaltung!.Raum!.Spielstaette!.Name,
145	                b.Veranstaltung!.Raum!.Name,
146	                b.Name,
147	                b.Email,
148	                b.Status.ToString(),
149	                b.Gesamtpreis,
150	                b.Buchungspositionen
151	                    .OrderBy(p => p.SitzplatzCode)
152	                    .Select(p => new BuchungspositionDto(p.SitzplatzCode, p.PreiskategorieId, p.Preiskategorie!.Name, p.PreisSnapshot))
153	                    .ToList()))
154	            .FirstOrDefaultAsync();
155	    }
156	}
